pub struct AnthropicOAuthProvider {
    pool: Arc<Pool>,
}

impl AnthropicOAuthProvider {
    pub fn new(pool: Arc<Pool>) -> Self {
        Self { pool }
    }
}

impl Provider for AnthropicOAuthProvider {
    fn id(&self) -> &str {
        "anthropic"
